INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "汤和", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年夺桥取和阳，后从朱渡江。", "biography": null, "status": "draft", "id": "76a3c1b3-e175-593d-99d7-63da30cef072"}, {"name": "刘继祖（朱元璋同乡）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "刘继祖是朱元璋的同乡。朱家没有地方安葬亡故的亲人时，他把土地给了朱家。", "biography": null, "status": "draft", "id": "2e65780b-449d-5b1f-a3d2-049df703491e"}, {"name": "沐英", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "定远人，父母亡，朱元璋收养、赐朱姓。", "biography": null, "status": "draft", "id": "c9e9d78a-2557-5892-876e-b1e99dd22bed"}, {"name": "蓝玉", "aliases": ["藍玉"], "era": "明", "birth_year": null, "death_year": null, "description": "明初将领。本纪载其以都督身份随西平侯沐英征讨西番。", "biography": null, "status": "draft", "id": "b9acd0d9-69b0-5100-b509-064627c8b88a"}, {"name": "丁玉", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，洪武6年（1373年）六月，丁玉出任参知政事。", "biography": null, "status": "draft", "id": "785c013f-f2ab-50b1-9261-1cc576a9cfb0"}, {"name": "李文忠", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "朱元璋姊子，1354年归舅获赐朱姓。", "biography": null, "status": "draft", "id": "937816d2-8a96-5b84-9cae-f26cdcacfa7b"}, {"name": "仇成", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "吴将，1366年围苏军西南。", "biography": null, "status": "draft", "id": "016fd8ef-c408-5d16-89e9-dd7976a9813d"}, {"name": "汪广洋", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年任朱元璋帅府令史。", "biography": null, "status": "draft", "id": "ac800e6b-ef48-5dc3-964b-d67d64245b02"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明廷拒收高丽使节来贡", "description": "本纪记载，占城、三佛齐、暹罗、爪哇和真腊都在这一年入贡。高丽使者五次来到明朝，明廷以高丽的继位者尚未正式确立为由，拒收来贡。 按原历纪年，事情发生在公元1377至1378年之间。", "start_year": null, "end_year": null, "time_original": "洪武十年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "58e39e03-6db0-5a66-b5c6-9bf0ac4dad2a"}, {"title": "明廷册封五名皇子并改封吴王", "description": "朱元璋封朱椿为蜀王、朱柏为湘王、朱桂为豫王、朱楧为汉王、朱植为卫王，同时将原来的吴王朱橚改封为周王。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年正月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "90933059-db82-5a69-8369-aac64f299ff2"}, {"title": "汤和进封信国公", "description": "朱元璋将汤和进封为信国公。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年正月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2fd6682d-0916-591c-9d85-a88433900b5e"}, {"title": "明廷召布政使和知府入朝", "description": "明廷在正月召各地的布政使和知府入朝。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7d3483cc-6ed9-5259-8c86-5ef3cf3a8287"}, {"title": "胡渊平定茂州战事", "description": "本纪记载，指挥胡渊于二月平定茂州的战事。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bb9bc986-4b3a-52e1-a754-b191c6102f10"}, {"title": "朱元璋命上奏无须先报中书省", "description": "朱元璋下令，官员奏事无须事先向中书省报告。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年三月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f5892916-dd80-5235-a5bb-2a7a9ea86f48"}, {"title": "明廷给入朝官员分等", "description": "明廷将来朝的官员评为三个等次。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2b6c6ba3-0e33-5af3-9491-b819d58838bf"}, {"title": "本纪记元廷君主去世及继位", "description": "《明史》本纪记载，元廷君主爱猷识理达腊在四月去世，脱古思帖木儿随后继位。双方的亲属关系仍需核对其他记载。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "30f47aee-4edf-52c7-826f-8c0b2a90a796"}, {"title": "明廷赈济苏松嘉湖水灾", "description": "明廷派人慰问苏、松、嘉、湖受水灾的百姓，每户发米一石，并免去积欠的赋税六十五万余。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年五月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bfa94b0a-8dab-52ec-80ec-8b7aba1ad8e7"}, {"title": "明廷派使者祭故元君主", "description": "明廷派使者祭奠已经去世的元廷君主。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年六月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "267929fb-c87d-53ab-b7f5-32f57192bbdd"}, {"title": "明廷派杨仲名到五开平乱", "description": "五开发生反抗，靖州指挥过兴被杀。明廷任命辰州指挥杨仲名为总兵官，率军出讨。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年六月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6797bb87-c84f-549e-ab15-16e78d0e6693"}, {"title": "明廷赈济平阳饥荒", "description": "平阳发生饥荒，明廷下令赈济。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年七月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f27dbf51-d618-55ee-a43e-c9b400aa3ab0"}, {"title": "明廷派官员救济沿海灾民", "description": "苏、松、扬、台等地遭遇海水漫溢，明廷派官员慰问和救济灾民。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33826b8a-097e-5cf3-b5ce-07d33507e4e5"}, {"title": "明廷免征应天等地秋粮", "description": "明廷免去应天、太平、镇江、宁国和广德等府州的秋粮。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "15037973-c23d-5dc9-a25b-31112864ad27"}, {"title": "刘继祖获追封义惠侯", "description": "九月，明廷追封刘继祖为义惠侯。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年九月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d1e87c2a-1748-54a5-bddb-dbceb4355a05"}, {"title": "大祀殿落成", "description": "大祀殿于十月落成。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年十月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "552a5cd7-cd2b-5e5a-baeb-c36b8a9b1b17"}, {"title": "沐英率军西征", "description": "征西将军、西平侯沐英率都督蓝玉、王弼出兵，征讨本纪所称的西番。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年十一月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1529f573-2629-5fee-8e03-9878bca48505"}, {"title": "五开战事平定", "description": "本纪记载，五开的战事在这个月平定。", "start_year": 1378, "end_year": 1378, "time_original": "洪武十一年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "86f2ffba-34d9-53eb-9917-0fef48975760"}, {"title": "暹罗等地遣使来贡", "description": "本纪列出本年入贡的各地，包括暹罗、阇婆、高丽、琉球、占城、三佛齐、朵甘、乌斯藏、彭亨和百花，未分别列出各批来使的日期。 按原历纪年，事情发生在公元1378至1379年之间。", "start_year": null, "end_year": null, "time_original": "洪武十一年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c21c734a-7de0-5614-9ea4-2166845b6d20"}, {"title": "明廷首次在南郊合祭天地", "description": "明廷第一次在南郊合祭天地。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年正月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "be264317-d192-537e-a51d-1bfae218e322"}, {"title": "明廷命沐英移兵洮州", "description": "洮州十八族发生反抗，明廷命沐英调兵前往征讨。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年正月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d1765553-ff7f-5b15-8ecf-896d802ea912"}, {"title": "丁玉平定松州战事", "description": "本纪记载，丁玉率军平定松州的战事。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年正月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "49de3f22-18f1-553f-8228-3ff3f6302f40"}, {"title": "李文忠督理河岷临巩军务", "description": "朝廷命李文忠负责河、岷、临、巩各地的军务。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年二月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "113c298d-3627-5991-b82b-6318a10f007e"}, {"title": "明廷下令发钞救济贫民", "description": "这一年春天连日雨雪，许多贫民遭受饥寒。朝廷下令由主管官署发放宝钞救济。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年二月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d1aa2eca-a8d0-5aaf-b30b-d2cc47772758"}, {"title": "汤和率列侯在临清练兵", "description": "信国公汤和率领列侯到临清练兵。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年二月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0fb6ecaa-ff49-5da2-819b-71f2bcf021e5"}, {"title": "明廷免征北平田租", "description": "朝廷免去北平的田租。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年五月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cf8c2aa4-61de-5ee6-a813-b972bb61b5e9"}, {"title": "都督马云出兵大宁", "description": "都督马云率兵征讨大宁。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年六月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "213df225-73de-5e2e-8736-c7aba7ce7ee6"}, {"title": "丁玉回兵平定眉县战事", "description": "丁玉回师征讨眉县的武装，平定当地战事。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年七月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "870f1d09-9f0c-55f6-a820-94edc8c50f85"}, {"title": "李文忠回掌大都督府", "description": "李文忠返回，继续掌理大都督府事务。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年七月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "78912be0-1ca5-5307-aebf-215787ebce04"}, {"title": "明廷免去退休官员家中的差役", "description": "朝廷下诏，官员退休后免除其家差役，终身无须承担。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年八月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9ae4cd70-404c-584e-8ac1-ca3709a96aae"}, {"title": "沐英在西征中取胜", "description": "沐英在西征中击败对方，俘获本纪所称其部首领“三副使”。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年九月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2a211785-79de-5785-8602-a2414d568d99"}, {"title": "沐英班师，明廷封仇成蓝玉等十二人为侯", "description": "沐英班师，朝廷封仇成、蓝玉等十二人为侯。", "start_year": 1379, "end_year": 1379, "time_original": "洪武十二年十一月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "48df8187-28e3-57c4-9aba-a1c1f7268c8f"}, {"title": "大宁战事平定", "description": "本纪记载，大宁战事于这一日平定。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十二年十一月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "711e3bee-7674-563c-ae3e-d20f484103fb"}, {"title": "汪广洋被贬往海南，并被赐死", "description": "洪武12年（1379年）十二月，汪广洋被贬往海南，并被赐死。", "start_year": 1379, "end_year": 1379, "time_original": "洪武12年（1379年）十二月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "d1283172-77ac-5185-adb4-f9403bf58a53"}, {"title": "明廷征召博学老成之士入京", "description": "朝廷征召各地博学、有经验的士人到京师。", "start_year": 1380, "end_year": 1380, "time_original": "洪武十二年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ed91f32c-da20-581d-b84c-c06f471c3ba5"}, {"title": "占城等地遣使入贡", "description": "本纪在这一年列出六处入贡地点，包括占城、爪哇、暹罗、日本、安南和高丽。 按原历纪年，事情发生在公元1379至1380年之间。", "start_year": null, "end_year": null, "time_original": "洪武十二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3ee7d2b7-8f5f-5f4d-adb5-e3182b8c5a22"}, {"title": "明廷退回高丽进贡的金银", "description": "高丽进贡黄金一百斤、白银一万两。明廷认为与约定有出入，退回贡品。 按原历纪年，事情发生在公元1379至1380年之间。", "start_year": null, "end_year": null, "time_original": "洪武十二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4f002b07-eead-573a-8f97-2a069d9c0fbb"}]'::jsonb)
