INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "本纪记载，占城、三佛齐、暹罗、爪哇和真腊都在这一年入贡。高丽使者五次来到明朝，明廷以高丽的继位者尚未正式确立为由，拒收来贡。 按原历纪年，事情发生在公元1377至1378年之间。", "citation": "《明史》卷2·本纪第二·太祖二·mingshi-2f603db3d81e-p000611；洪武十年", "note": "原文：占城、三佛齊、暹羅、爪哇、真臘入貢。高麗使五至，以嗣王未立，卻之。；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "0e5180bc-4bf8-5017-9226-6f5851260518", "subject_id": "58e39e03-6db0-5a66-b5c6-9bf0ac4dad2a", "source_id": "62532dbd-a5d3-5e51-a2d1-c9ff099e1c98"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历洪武十年。DDBC历表换算所据为1377-02-17至1378-02-05，据此核对公元发生年份。", "citation": "《明史》卷2·本纪第二·太祖二·mingshi-2f603db3d81e-p000611；洪武十年", "note": "原文：占城、三佛齊、暹羅、爪哇、真臘入貢。高麗使五至，以嗣王未立，卻之。；核对说明：原历纪年按本段及相邻年条核对，史料未载的具体日保留为空。", "status": "draft", "id": "4c3a728b-dab6-52a2-82cd-cc78d67a1f1f", "subject_id": "58e39e03-6db0-5a66-b5c6-9bf0ac4dad2a", "source_id": "62532dbd-a5d3-5e51-a2d1-c9ff099e1c98"}, {"subject_table": "person", "field_path": "description", "claim_text": "朱元璋册封与改封皇子。", "citation": "《明史》卷2·本纪第二·太祖二·mingshi-2f603db3d81e-p000613；洪武十一年正月甲戌", "note": "原文：甲戌，封皇子椿為蜀王，柏湘王，桂豫王，楧漢王，植衞王。改封吳王橚為周王。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "95dfff7e-2390-5afb-a866-1ff0c1a2a0fb", "subject_id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e", "source_id": "db95ab5e-3dee-534e-8b41-6c5f06ca327d"}, {"subject_table": "event", "field_path": "description", "claim_text": "朱元璋封朱椿为蜀王、朱柏为湘王、朱桂为豫王、朱楧为汉王、朱植为卫王，同时将原来的吴王朱橚改封为周王。", "citation": "《明史》卷2·本纪第二·太祖二·mingshi-2f603db3d81e-p000613；洪武十一年正月甲戌", "note": "原文：甲戌，封皇子椿為蜀王，柏湘王，桂豫王，楧漢王，植衞王。改封吳王橚為周王。；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "bb2151f7-4625-5068-8175-7fb71eaad6b2", "subject_id": "90933059-db82-5a69-8369-aac64f299ff2", "source_id": "db95ab5e-3dee-534e-8b41-6c5f06ca327d"}, {"subject_table": "event", "field_path": "time_